# 计算原始金额
order_amounts = {}
for order in sales:
    order_id = order['order_id']
    amount = order['quantity'] * order['unit_price']
    order_amounts[order_id] = {'category': order['category'], 'original': amount, 'adjusted': amount, 'product': order['product'], 'cancelled': False}

# 应用调整
adj_dict = {}
for adj in adjustments:
