    if data['cancelled']:
        print(f'{order_id}: {data[\"original\"]} -> {data[\"adjusted\"]} (CANCELLED) ({data[\"category\"]})')
    elif order_id in adj_dict and adj_dict[order_id]['type'] == 'partial_refund':
        print(f'{order_id}: {data[\"original\"]} -> {data[\"adjusted\"]} (refund: {adj_dict[order_id][\"amount_delta\"]}) ({data[\"category\"]})')
